B.a_V=s(["\u0985\u09a8\u09c1\u09b0\u09cb\u09a7 \u09ac\u09cd\u09af\u09b0\u09cd\u09a5 \u09b9\u09af\u09bc\u09c7\u099b\u09c7","\u062f\u0631\u062e\u0648\u0627\u0633\u062a \u0646\u0627\u06a9\u0627\u0645 \u06c1\u0648 \u06af\u0626\u06cc","\u0905\u0928\u0941\u0930\u094b\u0927 \u0935\u093f\u092b\u0932 \u0939\u0941\u0906"],t.s)
B.a_s=s(["\u09b8\u0982\u09b0\u0995\u09cd\u09b7\u09bf\u09a4 \u09b8\u09cd\u0995\u09cd\u09b0\u09bf\u09a8 \u09ab\u09bf\u09b0\u09bf\u09af\u09bc\u09c7 \u0986\u09a8\u09be \u09af\u09be\u09af\u09bc\u09a8\u09bf\u0964 \u0986\u09aa\u09a8\u09be\u09b0 \u0985\u09a8\u09b2\u09be\u0987\u09a8 \u0995\u09be\u099c \u0986\u09aa\u09a1\u09c7\u099f \u0995\u09b0\u09be \u09b9\u09ac\u09c7\u0964","\u0645\u062d\u0641\u0648\u0638 \u0627\u0633\u06a9\u0631\u06cc\u0646 \u0628\u062d\u0627\u0644 \u0646\u06c1\u06cc\u06ba \u06c1\u0648 \u0633\u06a9\u06cc\u06d4 \u0622\u067e \u06a9\u0627 \u0622\u0646 \u0644\u0627\u0626\u0646 \u06a9\u0627\u0645 \u062a\u0627\u0632\u06c1 \u06a9\u06cc\u0627 \u062c\u0627\u0626\u06d2 \u06af\u0627\u06d4","\u0938\u0939\u0947\u091c\u0940 \u0917\u0908 \u0938\u094d\u0915\u094d\u0930\u0940\u0928 \u0935\u093e\u092a\u0938 \u0928\u0939\u0940\u0902 \u0906 \u0938\u0915\u0940\u0964 \u0906\u092a\u0915\u093e \u0911\u0928\u0932\u093e\u0907\u0928 \u0915\u093e\u092e \u0905\u092a\u0921\u0947\u091f \u0939\u094b\u0917\u093e\u0964"],t.s)
B.W3=s(["\u09b8\u0982\u09af\u09cb\u0997 \u09ac\u09bf\u099a\u09cd\u099b\u09bf\u09a8\u09cd\u09a8\u0964 \u0986\u09ac\u09be\u09b0 \u099a\u09c7\u09b7\u09cd\u099f\u09be \u09b9\u099a\u09cd\u099b\u09c7; \u09a6\u09c7\u0996\u09be\u09a8\u09cb \u0985\u09a8\u09c1\u09b0\u09cb\u09a7 \u09aa\u09c1\u09b0\u09cb\u09a8\u09cb \u09b9\u09a4\u09c7 \u09aa\u09be\u09b0\u09c7\u0964","\u06a9\u0646\u06a9\u0634\u0646 \u0645\u0646\u0642\u0637\u0639 \u06c1\u0648 \u06af\u06cc\u0627\u06d4 \u062f\u0648\u0628\u0627\u0631\u06c1 \u06a9\u0648\u0634\u0634 \u06c1\u0648 \u0631\u06c1\u06cc \u06c1\u06d2\u061b \u062f\u06a9\u06be\u0627\u0626\u06cc \u06af\u0626\u06cc \u062f\u0631\u062e\u0648\u0627\u0633\u062a\u06cc\u06ba \u067e\u0631\u0627\u0646\u06cc \u06c1\u0648 \u0633\u06a9\u062a\u06cc \u06c1\u06cc\u06ba\u06d4","\u0915\u0928\u0947\u0915\u094d\u0936\u0928 \u091f\u0942\u091f\u093e\u0964 \u092b\u093f\u0930 \u0915\u094b\u0936\u093f\u0936 \u0939\u094b \u0930\u0939\u0940 \u0939\u0948; \u0926\u093f\u0916\u093e\u090f \u0917\u090f \u0905\u0928\u0941\u0930\u094b\u0927 \u092a\u0941\u0930\u093e\u0928\u0947 \u0939\u094b \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964"],t.s)
B.Ta=s(["\u09aa\u09c7\u09ae\u09c7\u09a8\u09cd\u099f \u09aa\u09cd\u09b0\u09af\u09bc\u09cb\u099c\u09a8\u0964 \u09a8\u09a4\u09c1\u09a8 \u0985\u09a8\u09c1\u09b0\u09cb\u09a7 \u0995\u09b0\u09be\u09b0 \u0986\u0997\u09c7 \u09ac\u0995\u09c7\u09af\u09bc\u09be \u09aa\u09b0\u09bf\u09b6\u09cb\u09a7 \u0995\u09b0\u09c1\u09a8\u0964","\u0627\u062f\u0627\u0626\u06cc\u06af\u06cc \u062f\u0631\u06a9\u0627\u0631 \u06c1\u06d2\u06d4 \u0646\u0626\u06cc \u062f\u0631\u062e\u0648\u0627\u0633\u062a \u0633\u06d2 \u067e\u06c1\u0644\u06d2 \u0628\u0642\u0627\u06cc\u0627 \u0627\u062f\u0627 \u06a9\u0631\u06cc\u06ba\u06d4","\u092d\u0941\u0917\u0924\u093e\u0928 \u091c\u093c\u0930\u0942\u0930\u0940 \u0939\u0948\u0964 \u0928\u092f\u093e \u0905\u0928\u0941\u0930\u094b\u0927 \u0915\u0930\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947 \u092c\u0915\u093e\u092f\u093e \u091a\u0941\u0915\u093e\u090f\u0901\u0964"],t.s)
B.a_k=s(["\u09ac\u09be\u09a4\u09bf\u09b2\u09c7\u09b0 \u09aa\u09b0\u09c7 \u09a8\u09a4\u09c1\u09a8 \u0985\u09a8\u09c1\u09b0\u09cb\u09a7 \u09b8\u09be\u09ae\u09af\u09bc\u09bf\u0995\u09ad\u09be\u09ac\u09c7 \u09ac\u09a8\u09cd\u09a7 \u0986\u099b\u09c7\u0964","\u0645\u0646\u0633\u0648\u062e\u06cc \u06a9\u06d2 \u0628\u0639\u062f \u0646\u0626\u06cc \u062f\u0631\u062e\u0648\u0627\u0633\u062a\u06cc\u06ba \u0639\u0627\u0631\u0636\u06cc \u0637\u0648\u0631 \u067e\u0631 \u0631\u06a9\u06cc \u06c1\u0648\u0626\u06cc \u06c1\u06cc\u06ba\u06d4","\u0930\u0926\u094d\u0926 \u0915\u0930\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0928\u090f \u0905\u0928\u0941\u0930\u094b\u0927 \u0915\u0941\u091b \u0938\u092e\u092f \u0915\u0947 \u0932\u093f\u090f \u0930\u0941\u0915\u0947 \u0939\u0948\u0902\u0964"],t.s)
B.a_O=s(["\u09ac\u09be\u09a4\u09bf\u09b2\u09c7\u09b0 \u09aa\u09b0\u09c7 \u0995\u09be\u099c \u0997\u09cd\u09b0\u09b9\u09a3 \u09b8\u09be\u09ae\u09af\u09bc\u09bf\u0995\u09ad\u09be\u09ac\u09c7 \u09ac\u09a8\u09cd\u09a7 \u0986\u099b\u09c7\u0964","\u0645\u0646\u0633\u0648\u062e\u06cc \u06a9\u06d2 \u0628\u0639\u062f \u06a9\u0627\u0645 \u0642\u0628\u0648\u0644 \u06a9\u0631\u0646\u0627 \u0639\u0627\u0631\u0636\u06cc \u0637\u0648\u0631 \u067e\u0631 \u0631\u06a9\u0627 \u06c1\u0648\u0627 \u06c1\u06d2\u06d4","\u0930\u0926\u094d\u0926 \u0915\u0930\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0915\u093e\u092e \u0938\u094d\u0935\u0940\u0915\u093e\u0930 \u0915\u0930\u0928\u093e \u0915\u0941\u091b \u0938\u092e\u092f \u0915\u0947 \u0932\u093f\u090f \u0930\u0941\u0915\u093e \u0939\u0948\u0964"],t.s)
B.WI=s(["\u09aa\u09cd\u09b0\u09a5\u09ae\u09c7 \u0995\u09be\u099c\u09c7\u09b0 \u09b8\u09cd\u09a5\u09be\u09a8\u09c7\u09b0 \u09e7\u09e6\u09e6 \u09ae\u09bf\u099f\u09be\u09b0\u09c7\u09b0 \u09ae\u09a7\u09cd\u09af\u09c7 \u09aa\u09cc\u0981\u099b\u09be\u09a8","\u067e\u06c1\u0644\u06d2 \u06a9\u0627\u0645 \u06a9\u06cc \u062c\u06af\u06c1 \u0633\u06d2 100 \u0645\u06cc\u0679\u0631 \u06a9\u06d2 \u0627\u0646\u062f\u0631 \u067e\u06c1\u0646\u0686\u06cc\u06ba","\u092a\u0939\u0932\u0947 \u0915\u093e\u092e \u0915\u0940 \u091c\u0917\u0939 \u0938\u0947 100 \u092e\u0940\u091f\u0930 \u0915\u0947 \u092d\u0940\u0924\u0930 \u092a\u0939\u0941\u0901\u091a\u0947\u0902"],t.s)
B.So=s(["\u09b6\u09c1\u09b0\u09c1 \u09b9\u0993\u09af\u09bc\u09be\u09b0 \u09aa\u09b0\u09c7 \u0995\u09be\u099c \u09ac\u09be\u09a4\u09bf\u09b2 \u0995\u09b0\u09be \u09af\u09be\u09ac\u09c7 \u09a8\u09be\u0964","\u0634\u0631\u0648\u0639 \u06c1\u0648\u0646\u06d2 \u06a9\u06d2 \u0628\u0639\u062f \u06a9\u0627\u0645 \u0645\u0646\u0633\u0648\u062e \u0646\u06c1\u06cc\u06ba \u06a9\u06cc\u0627 \u062c\u0627 \u0633\u06a9\u062a\u0627\u06d4","\u0936\u0941\u0930\u0942 \u0939\u094b\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0915\u093e\u092e \u0930\u0926\u094d\u0926 \u0928\u0939\u0940\u0902 \u0915\u093f\u092f\u093e \u091c\u093e \u0938\u0915\u0924\u093e\u0964"],t.s)
B.a_S=s(["\u09b6\u09c1\u09a7\u09c1 \u099a\u09b2\u09ae\u09be\u09a8 \u0995\u09be\u099c \u09b6\u09c7\u09b7 \u0995\u09b0\u09be \u09af\u09be\u09af\u09bc","\u0635\u0631\u0641 \u062c\u0627\u0631\u06cc \u06a9\u0627\u0645 \u0645\u06a9\u0645\u0644 \u06a9\u06cc\u0627 \u062c\u0627 \u0633\u06a9\u062a\u0627 \u06c1\u06d2","\u0938\u093f\u0930\u094d\u092b\u093c \u091a\u093e\u0932\u0942 \u0915\u093e\u092e \u092a\u0942\u0930\u093e \u0915\u093f\u092f\u093e \u091c\u093e \u0938\u0915\u0924\u093e \u0939\u0948"],t.s)
B.YG=s(["\u0985\u09ac\u09b8\u09cd\u09a5\u09be\u09a8\u09c7\u09b0 \u09b8\u0982\u09af\u09cb\u0997 \u09ac\u09bf\u099a\u09cd\u099b\u09bf\u09a8\u09cd\u09a8\u0964 \u0986\u09ac\u09be\u09b0 \u099a\u09c7\u09b7\u09cd\u099f\u09be \u09b9\u099a\u09cd\u099b\u09c7\u0964","\u0645\u0642\u0627\u0645 \u06a9\u0627 \u06a9\u0646\u06a9\u0634\u0646 \u0645\u0646\u0642\u0637\u0639 \u06c1\u0648 \u06af\u06cc\u0627\u06d4 \u062f\u0648\u0628\u0627\u0631\u06c1 \u06a9\u0648\u0634\u0634 \u06c1\u0648 \u0631\u06c1\u06cc \u06c1\u06d2\u06d4","\u0938\u094d\u0925\u093e\u0928 \u0915\u093e \u0915\u0928\u0947\u0915\u094d\u0936\u0928 \u091f\u0942\u091f\u093e\u0964 \u092b\u093f\u0930 \u0915\u094b\u0936\u093f\u0936 \u0939\u094b \u0930\u0939\u0940 \u0939\u0948\u0964"],t.s)
B.WB=s(["\u0985\u09ac\u09b8\u09cd\u09a5\u09be\u09a8 \u0986\u09aa\u09a1\u09c7\u099f \u09ac\u09cd\u09af\u09b0\u09cd\u09a5\u0964 \u09b8\u0982\u09af\u09cb\u0997 \u09aa\u09b0\u09c0\u0995\u09cd\u09b7\u09be \u0995\u09b0\u09c1\u09a8\u0964","\u0645\u0642\u0627\u0645 \u0627\u067e \u0688\u06cc\u0679 \u0646\u06c1\u06cc\u06ba \u06c1\u0648\u0627\u06d4 \u06a9\u0646\u06a9\u0634\u0646 \u0686\u06cc\u06a9 \u06a9\u0631\u06cc\u06ba\u06d4","\u0938\u094d\u0925\u093e\u0928 \u0905\u092a\u0921\u0947\u091f \u0928\u0939\u0940\u0902 \u0939\u0941\u0906\u0964 \u0915\u0928\u0947\u0915\u094d\u0936\u0928 \u091c\u093e\u0901\u091a\u0947\u0902\u0964"],t.s)
B.a04=s(["\u099c\u09bf\u09aa\u09bf\u098f\u09b8 \u09ac\u09a8\u09cd\u09a7 \u09b9\u09af\u09bc\u09c7\u099b\u09c7\u0964 \u0985\u09a8\u09c1\u09ae\u09a4\u09bf \u09aa\u09b0\u09c0\u0995\u09cd\u09b7\u09be \u0995\u09b0\u09c7 \u09b6\u09c7\u09af\u09bc\u09be\u09b0 \u0986\u09ac\u09be\u09b0 \u099a\u09be\u09b2\u09c1 \u0995\u09b0\u09c1\u09a8\u0964","GPS \u0631\u06a9 \u06af\u06cc\u0627\u06d4 \u0627\u062c\u0627\u0632\u062a\u06cc\u06ba \u0686\u06cc\u06a9 \u06a9\u0631\u06a9\u06d2 \u0634\u06cc\u0626\u0631\u0646\u06af \u062f\u0648\u0628\u0627\u0631\u06c1 \u0634\u0631\u0648\u0639 \u06a9\u0631\u06cc\u06ba\u06d4","GPS \u0930\u0941\u0915 \u0917\u092f\u093e\u0964 \u0905\u0928\u0941\u092e\u0924\u093f\u092f\u093e\u0901 \u091c\u093e\u0901\u091a\u0947\u0902 \u0914\u0930 \u0938\u093e\u091d\u093e \u0915\u0930\u0928\u093e \u092b\u093f\u0930 \u0936\u0941\u0930\u0942 \u0915\u0930\u0947\u0902\u0964"],t.s)
